import { useCallback, useEffect, useState } from 'react';
import Head from 'next/head';
import { adminFetch, adminMutation, apiErrorMessage, toQuery } from '@/lib/admin-client';

type Rule = { field: string; operator: string; value: string };
type Segment = { id: string; name_ar: string; description_ar?: string; definition: { match?: 'all' | 'any'; rules?: Rule[] }; count_current?: number | null; count_at_creation?: number; updatedAt?: string };
type Fields = { allowed_fields: Array<{ key?: string; field?: string; label_ar?: string; operators?: string[] }> };
type Preview = { count: number; sample: Array<{ id: string; full_name?: string; phone?: string; city?: string }>; compiled_filter: Record<string, unknown> };

export default function SegmentsPage() {
  const [segments, setSegments] = useState<Segment[]>([]); const [fields, setFields] = useState<Fields>({ allowed_fields: [] }); const [rules, setRules] = useState<Rule[]>([]); const [match, setMatch] = useState<'all' | 'any'>('all'); const [name, setName] = useState(''); const [description, setDescription] = useState(''); const [reason, setReason] = useState(''); const [preview, setPreview] = useState<Preview | null>(null); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState('');
  const load = useCallback(async () => { setLoading(true); setError(''); try { const [listed, allowed] = await Promise.all([adminFetch<Segment[]>('/segments'), adminFetch<Fields>('/segments/fields')]); setSegments(listed); setFields(allowed); if (!rules.length && allowed.allowed_fields.length) { const first: any = allowed.allowed_fields[0]; setRules([{ field: first.key || first.field || '', operator: first.operators?.[0] || 'eq', value: '' }]); } } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تحميل الشرائح.')); } finally { setLoading(false); } }, [rules.length]);
  useEffect(() => { void load(); }, [load]);
  function definition() { return { match, rules: rules.map((rule) => ({ ...rule, value: rule.value.trim() })) }; }
  function setRule(index: number, patch: Partial<Rule>) { setRules((items) => items.map((rule, i) => i === index ? { ...rule, ...patch } : rule)); }
  async function runPreview() { setSaving(true); setError(''); try { setPreview(await adminMutation<Preview>('/segments/preview', 'POST', { definition: definition() })); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر معاينة الشريحة.')); } finally { setSaving(false); } }
  async function save(event: React.FormEvent) { event.preventDefault(); if (!name.trim() || !rules.length || reason.trim().length < 5) { setError('اسم الشريحة وقاعدة واحدة على الأقل وسبب من خمسة أحرف مطلوبة.'); return; } setSaving(true); try { await adminMutation('/segments', 'POST', { name_ar: name.trim(), description_ar: description.trim(), definition: definition(), reason: reason.trim() }); setName(''); setDescription(''); setReason(''); setPreview(null); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر حفظ الشريحة.')); } finally { setSaving(false); } }
  async function remove(segment: Segment) { const why = window.prompt(`سبب حذف «${segment.name_ar}»:`); if (!why || why.trim().length < 5 || !window.confirm('سيتم حذف الشريحة وتسجيل ذلك في التدقيق. متابعة؟')) return; setSaving(true); try { await adminMutation(`/segments/${encodeURIComponent(segment.id)}`, 'DELETE', { reason: why.trim() }); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر حذف الشريحة.')); } finally { setSaving(false); } }
  return <><Head><title>شرائح العملاء | نبض</title></Head><section dir="rtl" className="space-y-6 p-6 md:p-8"><header><h1 className="text-3xl font-bold">شرائح العملاء الديناميكية</h1><p className="mt-1 text-sm text-slate-500">تعريف الجمهور ومعاينته يحولان قواعد الشريحة إلى استعلام خادمي على المستخدمين الحقيقيين.</p></header>{error ? <p role="alert" className="rounded-lg bg-rose-50 p-3 text-rose-700">{error}</p> : null}<div className="grid gap-6 lg:grid-cols-2"><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">الشريحة المحفوظة</h2>{loading ? <p className="mt-4 text-sm text-slate-500">جارٍ تحميل الشرائح…</p> : <ul className="mt-4 divide-y">{segments.length ? segments.map((segment) => <li key={segment.id} className="flex items-start justify-between gap-3 py-3"><div><strong>{segment.name_ar}</strong><p className="mt-1 text-sm text-slate-500">{segment.description_ar || 'لا يوجد وصف'}</p><p className="mt-1 text-xs text-slate-500">العدد الآن: {segment.count_current ?? 'غير متاح'} · عند الإنشاء: {segment.count_at_creation ?? '—'}</p></div><button disabled={saving} onClick={() => void remove(segment)} className="rounded border border-rose-300 px-3 py-1 text-xs text-rose-700">حذف</button></li>) : <li className="py-6 text-center text-sm text-slate-500">لا توجد شرائح محفوظة.</li>}</ul>}</article><form onSubmit={save} className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">إنشاء شريحة</h2><div className="mt-4 space-y-4"><input value={name} onChange={(e) => setName(e.target.value)} className="w-full rounded-lg border p-2" placeholder="اسم الشريحة بالعربية" required/><textarea value={description} onChange={(e) => setDescription(e.target.value)} className="min-h-16 w-full rounded-lg border p-2" placeholder="وصف اختياري"/><label className="block text-sm font-medium">مطابقة القواعد<select value={match} onChange={(e) => setMatch(e.target.value as 'all' | 'any')} className="mt-1 w-full rounded-lg border p-2"><option value="all">كل القواعد</option><option value="any">أي قاعدة</option></select></label><div className="space-y-3">{rules.map((rule, index) => <div key={index} className="grid gap-2 rounded-lg bg-slate-50 p-3 md:grid-cols-4"><select value={rule.field} onChange={(e) => setRule(index, { field: e.target.value })} className="rounded border p-2 text-sm">{fields.allowed_fields.map((field: any) => <option key={field.key || field.field} value={field.key || field.field}>{field.label_ar || field.key || field.field}</option>)}</select><input value={rule.operator} onChange={(e) => setRule(index, { operator: e.target.value })} className="rounded border p-2 text-sm" placeholder="operator"/><input value={rule.value} onChange={(e) => setRule(index, { value: e.target.value })} className="rounded border p-2 text-sm" placeholder="القيمة"/><button type="button" disabled={rules.length === 1} onClick={() => setRules((items) => items.filter((_, itemIndex) => itemIndex !== index))} className="rounded border px-2 text-sm disabled:opacity-40">حذف القاعدة</button></div>)}</div><button type="button" onClick={() => setRules((items) => [...items, { field: fields.allowed_fields[0] ? ((fields.allowed_fields[0] as any).key || (fields.allowed_fields[0] as any).field) : '', operator: 'eq', value: '' }])} className="rounded border px-3 py-2 text-sm">إضافة قاعدة</button><label className="block text-sm font-medium">سبب الإنشاء<textarea required minLength={5} value={reason} onChange={(e) => setReason(e.target.value)} className="mt-1 min-h-20 w-full rounded border p-2"/></label><div className="flex flex-wrap gap-2"><button type="button" disabled={saving} onClick={() => void runPreview()} className="rounded border border-teal-700 px-4 py-2 text-sm font-bold text-teal-800">معاينة الجمهور</button><button disabled={saving} className="rounded bg-teal-700 px-4 py-2 text-sm font-bold text-white">حفظ وتدقيق</button></div>{preview ? <div className="rounded-lg bg-teal-50 p-3 text-sm"><strong>عدد الأعضاء المطابقين: {preview.count}</strong><ul className="mt-2 space-y-1">{preview.sample.map((user) => <li key={user.id}>{user.full_name || user.id} · {user.city || '—'}</li>)}</ul></div> : null}</div></form></div></section></>;
}
